 "content": "def transform(grid):
    """Extend rightmost-edge rows of substantial 8-connected foreground objects."""
    if not grid:
        return []
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    while unseen:
        seed = unseen.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    p = (rr, cc)
                    if p in unseen:
                        unseen.remove(p)
                        comp.add(p)
                        stack.append(p)
