        if len(comp) < 3:
            continue
        right = max(c for r, c in comp)
        edge_rows = {r for r, c in comp if c == right}
        for r in edge_rows:
            for c in range(right + 1, w):
                if grid[r][c] == bg:
                    out[r][c] = 1
    return out
